"use client";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface GooeyHoverRevealProps
  extends Pick<
    ShaderSurfaceOptions,
    | "children"
    | "className"
    | "style"
    | "height"
    | "image"
    | "alt"
    | "radius"
    | "duration"
    | "intensity"
    | "maxDpr"
    | "onReady"
  > {
  coverColor?: string;
  revealed?: boolean;
}
/** Overlapping metaballs expose content through a decaying liquid mask. Keyboard/touch show content. */
export function GooeyHoverReveal({
  coverColor = "#f0f0f0",
  revealed = false,
  ...props
}: GooeyHoverRevealProps) {
  return (
    <ShaderSurface
      kind="gooey"
      radius={80}
      duration={1.6}
      colors={[coverColor]}
      progress={revealed ? 1 : 0}
      {...props}
    />
  );
}
